; =============================================================================
; Final Fantasy Legend III (U) [!].gb  (SaGa 3, Square 1993) - sound driver
; Bank $0F $4000-$6BAE + ROM0 caller $1F27-$1F44.  Generated by tools/gen_ffl3.py.
; Rebuilds byte-exact with RGBDS 0.9.x:
;   rgbasm -Wall -o ffl3snd.o FFL3_SoundDriver.asm
;   rgblink -o ffl3snd.gb ffl3snd.o ; then compare the two ranges (tools/cmp_ranges.py)
; =============================================================================

; ---------------------------------------------------------------- hardware

DEF rNR10    EQU $FF10
DEF rNR11    EQU $FF11
DEF rNR12    EQU $FF12
DEF rNR13    EQU $FF13
DEF rNR14    EQU $FF14
DEF rNR21    EQU $FF16
DEF rNR22    EQU $FF17
DEF rNR23    EQU $FF18
DEF rNR24    EQU $FF19
DEF rNR30    EQU $FF1A
DEF rNR31    EQU $FF1B
DEF rNR32    EQU $FF1C
DEF rNR33    EQU $FF1D
DEF rNR34    EQU $FF1E
DEF rNR41    EQU $FF20
DEF rNR42    EQU $FF21
DEF rNR43    EQU $FF22
DEF rNR44    EQU $FF23
DEF rNR50    EQU $FF24
DEF rNR51    EQU $FF25
DEF rNR52    EQU $FF26
DEF rWY      EQU $FF4A

; ---------------------------------------------------------------- HRAM
DEF hSongRequest    EQU $FFBA
DEF hSongCurrent    EQU $FFBB
DEF hSfxRequest     EQU $FFBC
DEF hFxChannel      EQU $FFBD
DEF hCh2TimerCopy   EQU $FFBE
DEF hCh1TimerCopy   EQU $FFBF
DEF hCh3TimerCopy   EQU $FFC0
DEF hCh4TimerCopy   EQU $FFC1
DEF hWavePtr        EQU $FFC2
DEF hSfxToneCount   EQU $FFC4
DEF hSfxNoiseCount  EQU $FFC5

; ---------------------------------------------------------------- WRAM
; Four channel structs of $18 bytes, in the driver's own order CH2, CH1, CH3, CH4.
;  +$00 LoopA      loop counter A          +$0A Freq (2)  current base period, hi has the trigger bit
;  +$01 LoopB      loop counter B                         (CH4: +$0A = NR43 copy)
;  +$02 SfxTimer   SFX frame timer (CH1/CH4) +$0C PitchTimer, +$0D PitchStart (2), +$0F PitchCur (2)
;  +$03 Stopped    $FF = track ended        +$11 VolTimer,   +$12 VolStart (2),   +$14 VolCur (2)
;  +$04 Timer      ticks left on this note  +$16 Duty       (CH1: NR11 copy for SFX restore)
;  +$05 Note       high nibble of the note  +$17 Pan        (CH1/CH4: NR51 bits for SFX restore)
;  +$06 Octave     octave*24 (byte offset into NoteFreqTable)
;  +$07 Ptr (2)    stream pointer           +$09 Volume     (CH3: NR32 value)
DEF wTempoAcc     EQU $CB00
DEF wTempo        EQU $CB01
DEF wCh2LoopA         EQU $CB02
DEF wCh2LoopB         EQU $CB03
DEF wCh2SfxTimer      EQU $CB04
DEF wCh2Stopped       EQU $CB05
DEF wCh2Timer         EQU $CB06
DEF wCh2Note          EQU $CB07
DEF wCh2Octave        EQU $CB08
DEF wCh2Ptr           EQU $CB09
DEF wCh2Volume        EQU $CB0B
DEF wCh2Freq          EQU $CB0C
DEF wCh2PitchTimer    EQU $CB0E
DEF wCh2PitchStart    EQU $CB0F
DEF wCh2PitchCur      EQU $CB11
DEF wCh2VolTimer      EQU $CB13
DEF wCh2VolStart      EQU $CB14
DEF wCh2VolCur        EQU $CB16
DEF wCh2Duty          EQU $CB18
DEF wCh2Pan           EQU $CB19
DEF wCh1LoopA         EQU $CB1A
DEF wCh1LoopB         EQU $CB1B
DEF wCh1SfxTimer      EQU $CB1C
DEF wCh1Stopped       EQU $CB1D
DEF wCh1Timer         EQU $CB1E
DEF wCh1Note          EQU $CB1F
DEF wCh1Octave        EQU $CB20
DEF wCh1Ptr           EQU $CB21
DEF wCh1Volume        EQU $CB23
DEF wCh1Freq          EQU $CB24
DEF wCh1PitchTimer    EQU $CB26
DEF wCh1PitchStart    EQU $CB27
DEF wCh1PitchCur      EQU $CB29
DEF wCh1VolTimer      EQU $CB2B
DEF wCh1VolStart      EQU $CB2C
DEF wCh1VolCur        EQU $CB2E
DEF wCh1Duty          EQU $CB30
DEF wCh1Pan           EQU $CB31
DEF wCh3LoopA         EQU $CB32
DEF wCh3LoopB         EQU $CB33
DEF wCh3SfxTimer      EQU $CB34
DEF wCh3Stopped       EQU $CB35
DEF wCh3Timer         EQU $CB36
DEF wCh3Note          EQU $CB37
DEF wCh3Octave        EQU $CB38
DEF wCh3Ptr           EQU $CB39
DEF wCh3Volume        EQU $CB3B
DEF wCh3Freq          EQU $CB3C
DEF wCh3PitchTimer    EQU $CB3E
DEF wCh3PitchStart    EQU $CB3F
DEF wCh3PitchCur      EQU $CB41
DEF wCh3VolTimer      EQU $CB43
DEF wCh3VolStart      EQU $CB44
DEF wCh3VolCur        EQU $CB46
DEF wCh3Duty          EQU $CB48
DEF wCh3Pan           EQU $CB49
DEF wCh4LoopA         EQU $CB4A
DEF wCh4LoopB         EQU $CB4B
DEF wCh4SfxTimer      EQU $CB4C
DEF wCh4Stopped       EQU $CB4D
DEF wCh4Timer         EQU $CB4E
DEF wCh4Note          EQU $CB4F
DEF wCh4Octave        EQU $CB50
DEF wCh4Ptr           EQU $CB51
DEF wCh4Volume        EQU $CB53
DEF wCh4Freq          EQU $CB54
DEF wCh4PitchTimer    EQU $CB56
DEF wCh4PitchStart    EQU $CB57
DEF wCh4PitchCur      EQU $CB59
DEF wCh4VolTimer      EQU $CB5B
DEF wCh4VolStart      EQU $CB5C
DEF wCh4VolCur        EQU $CB5E
DEF wCh4Duty          EQU $CB60
DEF wCh4Pan           EQU $CB61
DEF wSfxTonePtr     EQU $CB62
DEF wSfxNoisePtr    EQU $CB64
DEF wSfxToneHeld    EQU $CB66   ; != 0: CH1 music effects held (set while/after a CH1 SFX)
DEF wSfxNoiseHeld   EQU $CB67   ; same for CH4

; ---------------------------------------------------------------- music macros
; note byte = pitch << 4 | length index; pitch $0-$B = C..B, $C = tie, $D = rest
DEF C_ EQU 0
DEF Cs_ EQU 1
DEF D_ EQU 2
DEF Ds_ EQU 3
DEF E_ EQU 4
DEF F_ EQU 5
DEF Fs_ EQU 6
DEF G_ EQU 7
DEF Gs_ EQU 8
DEF A_ EQU 9
DEF As_ EQU 10
DEF B_ EQU 11
DEF L144 EQU 0
DEF L96  EQU 1
DEF L72  EQU 2
DEF L48  EQU 3
DEF L36  EQU 4
DEF L32  EQU 5
DEF L24  EQU 6
DEF L18  EQU 7
DEF L16  EQU 8
DEF L12  EQU 9
DEF L9   EQU 10
DEF L8   EQU 11
DEF L6   EQU 12
DEF L4   EQU 13
DEF L3   EQU 14
DEF L2   EQU 15

MACRO note      ; pitch, ticks
    db (\1) << 4 | L\2
ENDM
MACRO tie       ; ticks: extend the previous note (no retrigger)
    db $C0 | L\1
ENDM
MACRO rest      ; ticks
    db $D0 | L\1
ENDM
MACRO octave    ; n (0-7): absolute
    db $E0 | (\1)
ENDM
MACRO oct_up    ; n (1-4)
    db $E8 | ((\1) - 1)
ENDM
MACRO oct_down  ; n (1-4)
    db $EC | ((\1) - 1)
ENDM
MACRO env       ; volume envelope (CH1/CH2/CH4)
    db $F0
    dw \1
ENDM
MACRO volume    ; CH3 only: NR32 value
    db $F0, \1
ENDM
MACRO jump
    db $F1
    dw \1
ENDM
MACRO loop_a    ; --A != 0 -> jump
    db $F2
    dw \1
ENDM
MACRO set_a
    db $F3, \1
ENDM
MACRO pitch_fx  ; CH1-CH3
    db $F4
    dw \1
ENDM
MACRO duty      ; CH1/CH2: NRx1 value
    db $F5, \1
ENDM
MACRO pan       ; 0 off, 1 right, 2 left, 3 both
    db $F6, \1
ENDM
MACRO tempo     ; CH2 only
    db $F7, \1
ENDM
MACRO wave      ; CH3 only: load wave RAM and retrigger
    db $F8
    dw \1
ENDM
MACRO loop_b    ; --B != 0 -> jump
    db $F9
    dw \1
ENDM
MACRO set_b
    db $FA, \1
ENDM
MACRO if_a      ; A == n -> jump
    db $FB, \1
    dw \2
ENDM
MACRO ignored   ; CH2 only: argument dropped (FFA double-time vestige)
    db $FC, \1
ENDM
MACRO init_ch2  ; tempo, pitch_fx, env, duty, pan
    db $FE, \1
    dw \2, \3
    db \4, \5
ENDM
MACRO init_ch1  ; pitch_fx, env, duty, pan
    db $FE
    dw \1, \2
    db \3, \4
ENDM
MACRO init_ch3  ; pitch_fx, volume, wave, pan
    db $FE
    dw \1
    db \2
    dw \3
    db \4
ENDM
MACRO end_track
    db $FF
ENDM

; ---------------------------------------------------------------- effect / SFX macros
MACRO fx        ; effect ticks (1/3 frames), value (NRx2 or signed period offset)
    db \1, (\2) & $FF
ENDM
MACRO fx_jump
    db 0
    dw \1
ENDM
MACRO sfx_tone  ; frames, NR10, NR11, NR12, NR13, NR14
    db \1, \2, \3, \4, \5, \6
ENDM
MACRO sfx_noise ; frames, NR42, NR43
    db \1, \2, \3
ENDM
MACRO sfx_count ; n
    db $F0 | (\1)
ENDM
MACRO sfx_loop  ; --count != 0 -> jump
    db $EF
    dw \1
ENDM
MACRO sfx_end
    db 0
ENDM

; =============================================================================
SECTION "SoundCaller", ROM0[$1F27]
; STAT interrupt ($0048 -> $C0BC -> here). Runs the sound driver once per frame.
DEF BankPush EQU $38E1   ; A = bank: switch and push on the game's bank stack
DEF BankPop  EQU $38FC
DEF StatGameHook EQU $3549
DEF wStatHookOn EQU $CD3D
StatIsr::
    push af
    push bc
    push de
    push hl
    call SoundUpdateFar
    ld a, [wStatHookOn]
    or a
    call nz, StatGameHook
    pop hl
    pop de
    pop bc
    pop af
    reti
SoundUpdateFar::        ; also called directly at $11DC (with the LCD off)
    ld a, BANK(SoundUpdate)
    call BankPush
    call SoundUpdate_Main
    jp BankPop

; =============================================================================
SECTION "Sound", ROMX[$4000], BANK[$0F]


SoundUpdate:
    jr SoundUpdate_Main               ; entry vector (the game calls SoundUpdate_Main directly)
    db $00

SoundInit:
    jr SoundReset                     ; entry vector: no caller found in the ROM; song 0 reaches the same code
    db $00

SoundUpdate_Main:
    push af
    push bc
    push de
    push hl
    ld a, [wCh1SfxTimer]              ; song changes wait until neither SFX channel is busy
    ld c, a
    ld a, [wCh4SfxTimer]
    or c
    jr nz, SoundUpdate_Main.l401C
    ld hl, hSongRequest
    ld a, [hli]
    cp [hl]
    call nz, StartRequestedSong       ; hSongRequest != hSongCurrent -> start it
.l401C:
    ldh a, [hSfxRequest]
    or a
    call nz, PlaySfx                  ; new SFX request?
    call MusicUpdate
    call SfxUpdate
    pop hl
    pop de
    pop bc
    pop af
    ret

StartRequestedSong:
    ld [hl], a                        ; hSongCurrent = request; 0 = stop everything
    or a
    jr nz, PlaySong

SoundReset:
    ld a, $FF
    ldh [rNR52], a
    ld a, $08                         ; NR12/NR22 = vol 0 + env up (DAC on, silent); NR32 = $08 (output level 0)
    ldh [rNR12], a
    ldh [rNR22], a
    ldh [rNR32], a
    call SilenceChannels
    ld a, $77
    ldh [rNR50], a
    ld a, $FF
    ldh [rNR51], a
    ld [wCh2Stopped], a
    ld [wCh1Stopped], a
    ld [wCh3Stopped], a
    ld [wCh4Stopped], a
    xor a
    ld [wCh1SfxTimer], a              ; note: wCh4SfxTimer is NOT cleared here
    ld [wTempo], a                    ; wTempo = 0 (no ticks until a song starts)
    ld hl, hSongRequest               ; clears hSongRequest..$FFC9
    ld c, $10
.l4060:
    ld [hli], a
    dec c
    jr nz, SoundReset.l4060
    ret

PlaySong:
    dec a
    cp $14                            ; ids 1-20 only; others just update hSongCurrent
    ret nc
    add a, a
    add a, a
    add a, a
    ld hl, SongTable
    ld e, a
    ld d, $00
    add hl, de
    ld a, [hli]
    ld [wCh2Ptr], a
    ld a, [hli]
    ld [wCh2Ptr+1], a
    ld a, [hli]
    ld [wCh1Ptr], a
    ld a, [hli]
    ld [wCh1Ptr+1], a
    ld a, [hli]
    ld [wCh3Ptr], a
    ld a, [hli]
    ld [wCh3Ptr+1], a
    ld a, [hli]
    ld [wCh4Ptr], a
    ld a, [hl]
    ld [wCh4Ptr+1], a
    ld hl, wTempoAcc
    ld a, $FF                         ; wTempoAcc = $FF, default tempo $3C (overridden by the song)
    ld [hli], a
    ld a, $3C
    ld [hli], a
    ld hl, wCh2LoopA
    call ClearChannelState
    ld hl, wCh1LoopA
    call ClearChannelState
    ld hl, wCh3LoopA
    call ClearChannelState
    ld hl, wCh4LoopA

ClearChannelState:
    xor a                             ; loopA = loopB = sfxTimer = stopped = 0, timer = 1
    ld [hli], a
    ld [hli], a
    ld [hli], a
    ld [hli], a
    inc a
    ld [hl], a
    ret

SilenceChannels:
    xor a
    ld [wSfxToneHeld], a
    ld [wSfxNoiseHeld], a
    ldh [rNR10], a
    ld a, $FF
    ldh [rNR13], a
    ldh [rNR23], a
    ldh [rNR31], a
    ldh [rNR33], a
    ld a, $07
    ldh [rNR14], a
    ldh [rNR24], a
    ldh [rNR34], a
    ld a, $00
    ldh [rNR42], a
    ld a, $80
    ldh [rNR44], a
    ret

SfxTone_Release:
    xor a
    ldh [rNR10], a
    ld a, [wCh1Duty]
    ldh [rNR11], a
    ld a, $00                         ; NR12 = 0: CH1 DAC off until the music plays its next note
    ldh [rNR12], a
    ld a, $FF
    ldh [rNR13], a
    ld a, $87
    ldh [rNR14], a
    ld a, [wCh1Pan]
    ld e, a
    ldh a, [rNR51]
    and $EE
    or e
    ldh [rNR51], a
    ret

SfxNoise_Release:
    ld a, $08                         ; NR42 = $08: vol 0, env up
    ldh [rNR42], a
    xor a
    ldh [rNR43], a
    ld a, $80
    ldh [rNR44], a
    ld a, [wCh4Pan]
    ld e, a
    ldh a, [rNR51]
    and $77
    or e
    ldh [rNR51], a
    ret

NoteFreqTable:
    ; period | $8000 (trigger bit); 7 octaves of 12 + 1; index = octave*24 + note*2
    dw $802C, $809D, $8107, $816B, $81C9, $8223, $8277, $82C7, $8312, $8358, $839B, $83DA
    dw $8416, $844E, $8483, $84B5, $84E5, $8511, $853B, $8563, $8589, $85AC, $85CE, $85ED
    dw $860B, $8627, $8642, $865B, $8672, $8689, $869E, $86B2, $86C4, $86D6, $86E7, $86F7
    dw $8706, $8714, $8721, $872D, $8739, $8744, $874F, $8759, $8762, $876B, $8773, $877B
    dw $8783, $878A, $8790, $8797, $879D, $87A2, $87A7, $87AC, $87B1, $87B6, $87BA, $87BE
    dw $87C1, $87C5, $87C8, $87CB, $87CE, $87D1, $87D4, $87D6, $87D9, $87DB, $87DD, $87DF
    dw $87E1, $87E2, $87E4, $87E6, $87E7, $87E9, $87EA, $87EB, $87EC, $87ED, $87EE, $87EF
    dw $87F0

NoteLengthTable:
    db $90, $60, $48, $30, $24, $20, $18, $12, $10, $0C, $09, $08, $06, $04, $03, $02

MusicUpdate:
    ld hl, wTempo
    ld a, [hld]
    add a, [hl]
    ld [hl], a
    jr nc, MusicUpdate.l41DC          ; tempo: wTempoAcc += wTempo each frame; on carry run TWO ticks
    call MusicTick
    call MusicTick
.l41DC:
    ldh a, [hFxChannel]               ; effects: one channel per frame (CH2, CH1, CH3+CH4)
    inc a
    cp $03
    jr nz, MusicUpdate.l41E4
    xor a
.l41E4:
    ldh [hFxChannel], a
    or a
    call z, Fx_Ch2
    ldh a, [hFxChannel]
    cp $01
    call z, Fx_Ch1
    ldh a, [hFxChannel]
    cp $02
    call z, Fx_Ch3
    ret

MusicTick:
    ld hl, wCh2Stopped
    ld a, [hli]
    inc a
    jr z, MusicTick_Ch1
    dec [hl]
    ld a, [hl]
    ldh [hCh2TimerCopy], a
    jr nz, MusicTick_Ch1
    ld hl, wCh2Ptr
    ld a, [hli]
    ld d, [hl]
    ld e, a
.l420C:
    ld a, [de]
    inc de
    cp $E0                            ; $E0-$FF: octave / command
    jr c, MusicTick.l4224
    cp $FF                            ; $FF = end of track
    jp nz, Ch2_Command
    ld [wCh2Stopped], a
.l421A:
    ld a, $FF
    ldh [rNR23], a
    ld a, $07
    ldh [rNR24], a
    jr MusicTick_Ch1
.l4224:
    ld hl, wCh2Ptr
    ld [hl], e
    inc l
    ld [hl], d
    call SplitNoteByte                ; A = length, E = note in low nibble
    ld hl, wCh2Timer
    ld [hli], a
    ld a, e
    and $0F
    ld [hl], a
    cp $0C                            ; $C = tie (no retrigger), $D = rest
    jr z, MusicTick_Ch1
    jr nc, MusicTick.l421A
    ld hl, wCh2Octave                 ; freq = NoteFreqTable[octave + note*2]
    call GetFreqPtr
    push hl
    ld hl, wCh2VolStart               ; NR22 = 2nd byte of the envelope = first volume
    ld a, [hli]
    ld h, [hl]
    ld l, a
    inc hl
    ld a, [hl]
    ldh [rNR22], a
    pop hl
    ld a, [hli]
    ld c, [hl]
    ld hl, wCh2Freq
    ldh [rNR23], a
    ld [hli], a
    ld a, c
    ldh [rNR24], a
    ld [hli], a
    call RestartFx                    ; restart pitch fx, then volume fx
    inc l
    call RestartFx

MusicTick_Ch1:
    ld hl, wCh1Stopped
    ld a, [hli]
    inc a
    jr z, MusicTick_Ch3
    dec [hl]
    ld a, [hl]
    ldh [hCh1TimerCopy], a
    jr nz, MusicTick_Ch3
    ld hl, wCh1Ptr
    ld a, [hli]
    ld d, [hl]
    ld e, a
.l4273:
    ld a, [de]
    inc de
    cp $E0
    jr c, MusicTick_Ch1.l428B
    cp $FF
    jp nz, Ch1_Command
    ld [wCh1Stopped], a
.l4281:
    ld a, $FF
    ldh [rNR13], a
    ld a, $07
    ldh [rNR14], a
    jr MusicTick_Ch3
.l428B:
    ld hl, wCh1Ptr
    ld [hl], e
    inc l
    ld [hl], d
    call SplitNoteByte
    ld hl, wCh1Timer
    ld [hli], a
    ld a, e
    and $0F
    ld [hl], a
    ld c, a
    ld a, [wCh1SfxTimer]              ; SFX on CH1: stream advances, nothing is written
    or a
    jr nz, MusicTick_Ch3
    ld a, c
    cp $0C
    jr z, MusicTick_Ch3
    jr nc, MusicTick_Ch1.l4281
    ld hl, wCh1Octave
    call GetFreqPtr
    push hl
    ld hl, wCh1VolStart
    ld a, [hli]
    ld h, [hl]
    ld l, a
    inc hl
    ld a, [hl]
    ldh [rNR12], a
    pop hl
    ld a, [hli]
    ld c, [hl]
    ld hl, wCh1Freq
    ldh [rNR13], a
    ld [hli], a
    ld a, c
    ldh [rNR14], a
    ld [hli], a
    call RestartFx
    inc l
    call RestartFx
    xor a                             ; clear wSfxToneHeld: fx may run again
    ld [wSfxToneHeld], a

MusicTick_Ch3:
    ld hl, wCh3Stopped
    ld a, [hli]
    inc a
    jr z, MusicTick_Ch4
    dec [hl]
    ld a, [hl]
    ldh [hCh3TimerCopy], a
    jr nz, MusicTick_Ch4
    ld hl, wCh3Ptr
    ld a, [hli]
    ld d, [hl]
    ld e, a
.l42E6:
    ld a, [de]
    inc de
    cp $E0
    jr c, MusicTick_Ch3.l42FC
    cp $FF
    jp nz, Ch3_Command
    ld [wCh3Stopped], a
    ldh [rNR33], a
    ld a, $07
    ldh [rNR34], a
    jr MusicTick_Ch4
.l42FC:
    ld hl, wCh3Ptr
    ld [hl], e
    inc l
    ld [hl], d
    call SplitNoteByte
    ld hl, wCh3Timer
    ld [hli], a
    ld a, e
    and $0F
    ld [hl], a
    cp $0C
    jr c, MusicTick_Ch3.l4318
    jr z, MusicTick_Ch4               ; tie: keep playing
    xor a                             ; rest on CH3 = output level 0
    ldh [rNR32], a
    jr MusicTick_Ch4
.l4318:
    ld hl, wCh3Octave
    call GetFreqPtr
    ld a, [hli]
    ld b, [hl]
    ld c, a
    ld hl, wCh3Volume
    ld a, [hli]
    ldh [rNR32], a                    ; NR32 = channel volume; NR33/NR34 written without the trigger bit
    ld a, c
    ldh [rNR33], a
    ld [hli], a
    ld a, b
    and $07
    ldh [rNR34], a
    ld [hli], a
    call RestartFx

MusicTick_Ch4:
    ld hl, wCh4Stopped
    ld a, [hli]
    inc a
    ret z
    dec [hl]
    ld a, [hl]
    ldh [hCh4TimerCopy], a
    ret nz
    ld hl, wCh4Ptr
    ld a, [hli]
    ld d, [hl]
    ld e, a
.l4345:
    ld a, [de]
    inc de
    cp $E0
    jr c, MusicTick_Ch4.l435C
    cp $FF
    jr nz, Ch4_Command
    ld [wCh4Stopped], a
.l4352:
    xor a
    ldh [rNR42], a
    ldh [rNR43], a
    ld a, $80
    ldh [rNR44], a
    ret
.l435C:
    ld hl, wCh4Ptr
    ld [hl], e
    inc l
    ld [hl], d
    call SplitNoteByte
    ld hl, wCh4Timer
    ld [hli], a
    ld a, e
    and $0F
    ld [hl], a
    ld e, a
    ld a, [wCh4SfxTimer]
    or a
    ret nz
    ld a, e
    cp $0C
    ret z
    jr nc, MusicTick_Ch4.l4352
    ld d, $00                         ; noise "pitch" = NR43 from NoiseNoteTable (octave unused)
    ld hl, NoiseNoteTable
    add hl, de
    ld c, [hl]
    ld hl, wCh4VolStart
    ld a, [hli]
    ld h, [hl]
    ld l, a
    inc hl
    ld a, [hl]
    ldh [rNR42], a
    ld a, c
    ldh [rNR43], a
    ld [wCh4Freq], a
    ld a, $80
    ldh [rNR44], a
    xor a
    ld [wSfxNoiseHeld], a
    ld hl, wCh4VolTimer

RestartFx:
    ld a, $01
    ld [hli], a
    ld a, [hli]
    ld e, [hl]
    inc l
    ld [hli], a
    ld [hl], e
    ret

Ch4_Command:
    ld hl, MusicTick_Ch4.l4345        ; CH4: every $E0-$FE byte is a command (low nibble)
    push hl                           ; handlers return to the stream-read loop
    ld hl, CmdTable_Ch4

DispatchCommand:
    and $0F
    add a, a
    ld c, a
    ld b, $00
    add hl, bc
    ld a, [hli]
    ld h, [hl]
    ld l, a
    jp hl

Ch3_Command:
    ld hl, MusicTick_Ch3.l42E6
    push hl
    cp $F0
    jr c, Ch3_Command.l43C3
    ld hl, CmdTable_Ch3
    jr DispatchCommand
.l43C3:
    ld bc, wCh3Octave
    jr OctaveCommand

Ch1_Command:
    ld hl, MusicTick_Ch1.l4273
    push hl
    cp $F0
    jr c, Ch1_Command.l43D5
    ld hl, CmdTable_Ch1
    jr DispatchCommand
.l43D5:
    ld bc, wCh1Octave
    jr OctaveCommand

Ch2_Command:
    ld hl, MusicTick.l420C
    push hl
    cp $F0
    jr c, Ch2_Command.l43E7
    ld hl, CmdTable_Ch2
    jr DispatchCommand
.l43E7:
    ld bc, wCh2Octave

OctaveCommand:
    push de                           ; bit 3 clear: octave = n*24 (absolute); set: += OctaveDeltaTable[n&7]
    bit 3, a
    jr nz, OctaveCommand.l43FA
    and $07
    add a, a
    add a, a
    add a, a
    ld e, a
    add a, a
    add a, e
    ld [bc], a
    pop de
    ret
.l43FA:
    and $07
    ld e, a
    ld d, $00
    ld hl, OctaveDeltaTable
    add hl, de
    ld a, [bc]
    add a, [hl]
    ld [bc], a
    pop de
    ret

SplitNoteByte:
    ld e, a
    swap e
    and $0F
    ld c, a
    ld b, $00
    ld hl, NoteLengthTable
    add hl, bc
    ld a, [hl]
    ret

GetFreqPtr:
    add a, a
    add a, [hl]
    ld c, a
    ld b, $00
    ld hl, NoteFreqTable
    add hl, bc
    ret

OctaveDeltaTable:
    db $18, $30, $48, $60, $E8, $D0, $B8, $A0

CmdTable_Ch2:
    dw Ch2_SetEnv           ; $F0
    dw Cmd_Jump             ; $F1
    dw Ch2_LoopA            ; $F2
    dw Ch2_SetLoopA         ; $F3
    dw Ch2_SetPitchFx       ; $F4
    dw Ch2_SetDuty          ; $F5
    dw Ch2_SetPan           ; $F6
    dw Cmd_SetTempo         ; $F7
    dw Cmd_Hang             ; $F8
    dw Ch2_LoopB            ; $F9
    dw Ch2_SetLoopB         ; $FA
    dw Ch2_IfLoopA          ; $FB
    dw Cmd_IgnoreByte       ; $FC
    dw Cmd_Hang             ; $FD
    dw Ch2_Init             ; $FE
    dw Cmd_Hang             ; $FF

CmdTable_Ch1:
    dw Ch1_SetEnv           ; $F0
    dw Cmd_Jump             ; $F1
    dw Ch1_LoopA            ; $F2
    dw Ch1_SetLoopA         ; $F3
    dw Ch1_SetPitchFx       ; $F4
    dw Ch1_SetDuty          ; $F5
    dw Ch1_SetPan           ; $F6
    dw Cmd_Hang             ; $F7
    dw Cmd_Hang             ; $F8
    dw Ch1_LoopB            ; $F9
    dw Ch1_SetLoopB         ; $FA
    dw Ch1_IfLoopA          ; $FB
    dw Cmd_Hang             ; $FC
    dw Cmd_Hang             ; $FD
    dw Ch1_Init             ; $FE
    dw Cmd_Hang             ; $FF

CmdTable_Ch3:
    dw Ch3_SetVolume        ; $F0
    dw Cmd_Jump             ; $F1
    dw Ch3_LoopA            ; $F2
    dw Ch3_SetLoopA         ; $F3
    dw Ch3_SetPitchFx       ; $F4
    dw Cmd_Hang             ; $F5
    dw Ch3_SetPan           ; $F6
    dw Cmd_Hang             ; $F7
    dw Ch3_LoadWave         ; $F8
    dw Ch3_LoopB            ; $F9
    dw Ch3_SetLoopB         ; $FA
    dw Ch3_IfLoopA          ; $FB
    dw Cmd_Hang             ; $FC
    dw Cmd_Hang             ; $FD
    dw Ch3_Init             ; $FE
    dw Cmd_Hang             ; $FF

CmdTable_Ch4:
    dw Ch4_SetEnv           ; $0
    dw Cmd_Jump             ; $1
    dw Ch4_LoopA            ; $2
    dw Ch4_SetLoopA         ; $3
    dw Cmd_Hang             ; $4
    dw Cmd_Hang             ; $5
    dw Ch4_SetPan           ; $6
    dw Cmd_Hang             ; $7
    dw Cmd_Hang             ; $8
    dw Ch4_LoopB            ; $9
    dw Ch4_SetLoopB         ; $A
    dw Ch4_IfLoopA          ; $B
    dw Cmd_Hang             ; $C
    dw Cmd_Hang             ; $D
    dw Cmd_Hang             ; $E
    dw Cmd_Hang             ; $F

Ch3_SetVolume:
    ld a, [de]
    inc de
    ld [wCh3Volume], a
    ldh [rNR32], a
    ret

Ch2_SetEnv:
    ld hl, wCh2VolStart
    jr StorePointerArg

Ch1_SetEnv:
    ld hl, wCh1VolStart
    jr StorePointerArg

Ch4_SetEnv:
    ld hl, wCh4VolStart
    jr StorePointerArg

Ch2_SetPitchFx:
    ld hl, wCh2PitchStart
    jr StorePointerArg

Ch1_SetPitchFx:
    ld hl, wCh1PitchStart
    jr StorePointerArg

Ch3_SetPitchFx:
    ld hl, wCh3PitchStart

StorePointerArg:
    ld a, [de]
    inc de
    ld [hli], a
    ld a, [de]
    inc de
    ld [hl], a
    ret

Ch2_SetLoopA:
    ld a, [de]
    inc de
    ld [wCh2LoopA], a
    ret

Ch1_SetLoopA:
    ld a, [de]
    inc de
    ld [wCh1LoopA], a
    ret

Ch3_SetLoopA:
    ld a, [de]
    inc de
    ld [wCh3LoopA], a
    ret

Ch4_SetLoopA:
    ld a, [de]
    inc de
    ld [wCh4LoopA], a
    ret

Ch2_SetLoopB:
    ld a, [de]
    inc de
    ld [wCh2LoopB], a
    ret

Ch1_SetLoopB:
    ld a, [de]
    inc de
    ld [wCh1LoopB], a
    ret

Ch3_SetLoopB:
    ld a, [de]
    inc de
    ld [wCh3LoopB], a
    ret

Ch4_SetLoopB:
    ld a, [de]
    inc de
    ld [wCh4LoopB], a
    ret

Ch2_LoopA:
    ld hl, wCh2LoopA
    jr LoopCommon

Ch1_LoopA:
    ld hl, wCh1LoopA
    jr LoopCommon

Ch3_LoopA:
    ld hl, wCh3LoopA
    jr LoopCommon

Ch4_LoopA:
    ld hl, wCh4LoopA
    jr LoopCommon

Ch2_LoopB:
    ld hl, wCh2LoopB
    jr LoopCommon

Ch1_LoopB:
    ld hl, wCh1LoopB
    jr LoopCommon

Ch3_LoopB:
    ld hl, wCh3LoopB
    jr LoopCommon

Ch4_LoopB:
    ld hl, wCh4LoopB

LoopCommon:
    dec [hl]                          ; loop: --counter; != 0 -> jump, else skip the pointer
    jr nz, Cmd_Jump

SkipPointerArg:
    inc de
    inc de
    ret

Ch2_IfLoopA:
    ld hl, wCh2LoopA
    jr IfLoopACommon

Ch1_IfLoopA:
    ld hl, wCh1LoopA
    jr IfLoopACommon

Ch3_IfLoopA:
    ld hl, wCh3LoopA
    jr IfLoopACommon

Ch4_IfLoopA:
    ld hl, wCh4LoopA
    jr IfLoopACommon

IfLoopACommon:
    ld a, [de]                        ; if counter A == arg -> jump, else skip the pointer
    inc de
    cp [hl]
    jr nz, SkipPointerArg

Cmd_Jump:
    ld l, e
    ld h, d
    ld a, [hli]
    ld d, [hl]
    ld e, a
    ret

Ch2_SetDuty:
    ld a, [de]
    inc de
    ldh [rNR21], a
    ld [wCh2Duty], a
    ret

Ch1_SetDuty:
    ld a, [de]
    inc de
    ld [wCh1Duty], a
    ld b, a
    ld a, [wCh1SfxTimer]
    or a
    ret nz
    ld a, b
    ldh [rNR11], a
    ret

Cmd_SetTempo:
    ld a, [de]
    inc de
    ld [wTempo], a
    ret

Ch3_LoadWave:
    ld a, [de]
    inc de
    ld c, a
    ldh [hWavePtr], a
    ld a, [de]
    inc de
    ldh [hWavePtr+1], a
    ld h, a
    ld l, c
    xor a
    ldh [rNR30], a
    ld c, $30
    ld b, $10
.l457D:
    ld a, [hli]
    ldh [c], a
    inc c
    dec b
    jr nz, Ch3_LoadWave.l457D
    ld a, $80
    ldh [rNR30], a
    xor a
    ldh [rNR32], a
    ld a, $87
    ldh [rNR34], a
    ret

Ch2_Init:
    call Cmd_SetTempo
    call Ch2_SetPitchFx
    call Ch2_SetEnv
    call Ch2_SetDuty

Ch2_SetPan:
    ld a, [de]
    inc de
    ld c, a
    ld b, $00
    ld hl, PanTable_Ch2
    add hl, bc
    ldh a, [rNR51]
    and $DD
    or [hl]
    ldh [rNR51], a
    ret

Ch1_Init:
    call Ch1_SetPitchFx
    call Ch1_SetEnv
    call Ch1_SetDuty

Ch1_SetPan:
    ld a, [de]
    inc de
    ld c, a
    ld b, $00
    ld hl, PanTable_Ch1
    add hl, bc
    ld a, [hl]
    ld [wCh1Pan], a
    ld a, [wCh1SfxTimer]
    or a
    ret nz
    ldh a, [rNR51]
    and $EE
    or [hl]
    ldh [rNR51], a
    ret

Ch3_Init:
    call Ch3_SetPitchFx
    call Ch3_SetVolume
    call Ch3_LoadWave

Ch3_SetPan:
    ld a, [de]
    inc de
    ld c, a
    ld b, $00
    ld hl, PanTable_Ch3
    add hl, bc
    ldh a, [rNR51]
    and $BB
    or [hl]
    ldh [rNR51], a
    ret

Ch4_SetPan:
    ld a, [de]
    inc de
    ld c, a
    ld b, $00
    ld hl, PanTable_Ch4
    add hl, bc
    ld a, [hl]
    ld [wCh4Pan], a
    ld a, [wCh4SfxTimer]
    or a
    ret nz
    ldh a, [rNR51]
    and $77
    or [hl]
    ldh [rNR51], a
    ret

PanTable_Ch2:
    db $00, $02, $20, $22

PanTable_Ch1:
    db $00, $01, $10, $11

PanTable_Ch3:
    db $00, $04, $40, $44

PanTable_Ch4:
    db $00, $08, $80, $88

Cmd_IgnoreByte:
    ld a, [de]                        ; vestige of FFA's $EC "double-time" command: argument read and dropped
    inc de
    ret

Cmd_Hang:
    jr Cmd_Hang                       ; undefined commands land here: infinite loop (freezes the game)
    db $C9                            ; orphan RET after the hang loop (also present in FFA)

NoiseNoteTable:
    db $64, $59, $54, $2F, $44, $34, $2E, $24, $2D, $14, $1D, $04

Fx_Ch2:
    ld hl, wCh2Stopped
    ld a, [hli]
    or a
    ret nz
    ldh a, [hCh2TimerCopy]            ; no effects while the timer copy is 0 (note started on the 2nd tick of a pair)
    or a
    ret z
    inc l                             ; no effects on rests
    ld a, [hl]
    cp $0D
    ret z
    ld hl, wCh2PitchTimer
    dec [hl]
    jr nz, Fx_Ch2.l465F
    call FxNextEntry
    ld [wCh2PitchTimer], a
    ld a, [hli]
    ld e, a
    ld d, $00
    ld c, h
    ld a, l
    ld hl, wCh2PitchCur
    ld [hli], a
    ld [hl], c
    bit 7, e
    jr z, Fx_Ch2.l4650
    dec d
.l4650:
    ld hl, wCh2Freq                   ; pitch = base + signed offset (no trigger)
    ld a, [hli]
    ld h, [hl]
    ld l, a
    add hl, de
    ld a, l
    ldh [rNR23], a
    ld a, h
    and $07
    ldh [rNR24], a
.l465F:
    ld hl, wCh2VolTimer
    ld a, [hl]
    inc a
    ret z
    dec [hl]
    ret nz
    call FxNextEntry
    ld [wCh2VolTimer], a
    ld a, [hli]
    ldh [rNR22], a
    ld a, [wCh2Freq+1]                ; volume step retriggers with the BASE frequency high byte
    ldh [rNR24], a
    ld c, h
    ld a, l
    ld hl, wCh2VolCur
    ld [hli], a
    ld [hl], c
    ret

Fx_Ch1:
    ld hl, wCh1SfxTimer
    ld a, [hli]
    or [hl]
    ret nz
    ldh a, [hCh1TimerCopy]
    or a
    ret z
    inc l
    inc l
    ld a, [hl]
    cp $0D
    ret z
    ld a, [wSfxToneHeld]              ; held after an SFX until the next note
    and a
    ret nz
    ld hl, wCh1PitchTimer
    dec [hl]
    jr nz, Fx_Ch1.l46BD
    call FxNextEntry
    ld [wCh1PitchTimer], a
    ld a, [hli]
    ld e, a
    ld d, $00
    ld c, h
    ld a, l
    ld hl, wCh1PitchCur
    ld [hli], a
    ld [hl], c
    bit 7, e
    jr z, Fx_Ch1.l46AE
    dec d
.l46AE:
    ld hl, wCh1Freq
    ld a, [hli]
    ld h, [hl]
    ld l, a
    add hl, de
    ld a, l
    ldh [rNR13], a
    ld a, h
    and $07
    ldh [rNR14], a
.l46BD:
    ld hl, wCh1VolTimer
    ld a, [hl]
    inc a
    ret z
    dec [hl]
    ret nz
    call FxNextEntry
    ld [wCh1VolTimer], a
    ld a, [hli]
    ldh [rNR12], a
    ld a, [wCh1Freq+1]
    ldh [rNR14], a
    ld c, h
    ld a, l
    ld hl, wCh1VolCur
    ld [hli], a
    ld [hl], c
    ret

Fx_Ch3:
    ld hl, wCh3Stopped
    ld a, [hli]
    or a
    jr nz, Fx_Ch4
    ldh a, [hCh3TimerCopy]
    or a
    jr z, Fx_Ch4
    inc l
    ld a, [hl]
    cp $0D
    jr z, Fx_Ch4
    ld hl, wCh3PitchTimer
    dec [hl]
    jr nz, Fx_Ch4
    call FxNextEntry
    ld [wCh3PitchTimer], a
    ld a, [hli]
    ld e, a
    ld d, $00
    ld c, h
    ld a, l
    ld hl, wCh3PitchCur
    ld [hli], a
    ld [hl], c
    bit 7, e
    jr z, Fx_Ch3.l4709
    dec d
.l4709:
    ld hl, wCh3Freq
    ld a, [hli]
    ld h, [hl]
    ld l, a
    add hl, de
    ld a, l
    ldh [rNR33], a
    ld a, h
    and $07
    ldh [rNR34], a

Fx_Ch4:
    ld hl, wCh4SfxTimer
    ld a, [hli]
    or [hl]
    ret nz
    ldh a, [hCh4TimerCopy]
    or a
    ret z
    inc l
    inc l
    ld a, [hl]
    cp $0D
    ret z
    ld hl, wCh4VolTimer
    ld a, [hl]
    inc a
    ret z
    dec [hl]
    ret nz
    ld a, [wSfxNoiseHeld]
    and a
    ret nz
    call FxNextEntry
    ld [wCh4VolTimer], a
    ld a, [hli]
    ldh [rNR42], a
    ld a, $80
    ldh [rNR44], a
    ld a, l
    ld [wCh4VolCur], a
    ld a, h
    ld [wCh4VolCur+1], a
    ret

FxNextEntry:
    inc l
    inc l
    inc l
    ld a, [hli]
    ld h, [hl]
    ld l, a
    ld a, [hli]                       ; entry: timer, value; timer 0 = jump to the following pointer
    or a
    ret nz
    ld a, [hli]
    ld h, [hl]
    ld l, a
    ld a, [hli]
    ret

PlaySfx:
    dec a                             ; A = SFX id (1-65), no range check, no priority
    add a, a
    ld e, a
    ld d, $00
    ld hl, SfxToneTable
    add hl, de
    push de
    ld a, [hli]
    ld c, [hl]
    add a, c                          ; pointer 0 = no part for that channel
    jr z, PlaySfx.l4775
    sub c
    ld de, wSfxTonePtr
    ld [de], a
    inc e
    ld a, c
    ld [de], a
    ld a, $01
    ld [wCh1SfxTimer], a
.l4775:
    pop de
    ld hl, SfxNoiseTable
    add hl, de
    ld a, [hli]
    ld c, [hl]
    add a, c
    jr z, PlaySfx.l478A
    sub c
    ld hl, wSfxNoisePtr
    ld [hli], a
    ld [hl], c
    ld a, $01
    ld [wCh4SfxTimer], a
.l478A:
    xor a
    ldh [hSfxRequest], a
    ret

SfxUpdate:
    ld de, wCh1SfxTimer
    ld a, [de]
    or a
    jr z, SfxUpdate_Noise
    ld [wSfxToneHeld], a
    dec a
    ld [de], a
    jr nz, SfxUpdate_Noise
    ld hl, wSfxTonePtr
    ld a, [hli]
    ld h, [hl]
    ld l, a
.l47A2:
    ld a, [hli]
    ld [de], a
    or a
    jr nz, SfxUpdate.l47AC            ; duration 0 = end
    call SfxTone_Release
    jr SfxUpdate_Noise
.l47AC:
    cp $EF                            ; $EF ptr = loop to ptr while --count != 0
    jr nz, SfxUpdate.l47BF
    ld a, [hli]
    ld c, a
    ld a, [hli]
    ld b, a
    ldh a, [hSfxToneCount]
    dec a
    ldh [hSfxToneCount], a
    jr z, SfxUpdate.l47A2
    ld l, c
    ld h, b
    jr SfxUpdate.l47A2
.l47BF:
    cp $F0                            ; $Fn = set loop count to n
    jr c, SfxUpdate.l47C9
    and $0F
    ldh [hSfxToneCount], a
    jr SfxUpdate.l47A2
.l47C9:
    ld c, $10                         ; tone frame: NR10..NR14
    ld b, $05
.l47CD:
    ld a, [hli]
    ldh [c], a
    inc c
    dec b
    jr nz, SfxUpdate.l47CD
    ldh a, [rNR51]
    or $11
    ldh [rNR51], a
    ld c, h
    ld a, l
    ld hl, wSfxTonePtr
    ld [hli], a
    ld [hl], c

SfxUpdate_Noise:
    ld de, wCh4SfxTimer
    ld a, [de]
    or a
    ret z
    ld [wSfxNoiseHeld], a
    dec a
    ld [de], a
    ret nz
    ld hl, wSfxNoisePtr
    ld a, [hli]
    ld h, [hl]
    ld l, a
.l47F2:
    ld a, [hli]
    ld [de], a
    or a
    jr nz, SfxUpdate_Noise.l47FA
    jp SfxNoise_Release
.l47FA:
    cp $EF
    jr nz, SfxUpdate_Noise.l480D
    ld a, [hli]
    ld c, a
    ld a, [hli]
    ld b, a
    ldh a, [hSfxNoiseCount]
    dec a
    ldh [hSfxNoiseCount], a
    jr z, SfxUpdate_Noise.l47F2
    ld l, c
    ld h, b
    jr SfxUpdate_Noise.l47F2
.l480D:
    cp $F0
    jr c, SfxUpdate_Noise.l4817
    and $0F
    ldh [hSfxNoiseCount], a
    jr SfxUpdate_Noise.l47F2
.l4817:
    ld a, [hli]
    ldh [rNR42], a
    ld a, [hli]
    ldh [rNR43], a
    ld a, $80
    ldh [rNR44], a
    ldh a, [rNR51]
    or $88
    ldh [rNR51], a
    ld c, h
    ld a, l
    ld hl, wSfxNoisePtr
    ld [hli], a
    ld [hl], c
    ret

SongTable:   ; 20 songs x (CH2, CH1, CH3, CH4)
    dw Song01_Ch2, Song01_Ch1, Song01_Ch3, Song01_Ch4 ; 1
    dw Song02_Ch2, Song02_Ch1, Song02_Ch3, Song02_Ch4 ; 2
    dw Song03_Ch2, Song03_Ch1, Song03_Ch3, Song03_Ch4 ; 3
    dw Song04_Ch2, Song04_Ch1, Song04_Ch3, Song04_Ch4 ; 4
    dw Song05_Ch2, Song05_Ch1, Song05_Ch3, Song05_Ch4 ; 5
    dw Song06_Ch2, Song06_Ch1, Song06_Ch3, Song06_Ch4 ; 6
    dw Song07_Ch2, Song07_Ch1, Song07_Ch3, Song07_Ch4 ; 7
    dw Song08_Ch2, Song08_Ch1, Song08_Ch3, Song08_Ch4 ; 8
    dw Song09_Ch2, Song09_Ch1, Song09_Ch3, Song09_Ch4 ; 9
    dw Song10_Ch2, Song10_Ch1, Song10_Ch3, Song03_Ch4 ; 10
    dw Song11_Ch2, Song11_Ch1, Song11_Ch3, Song11_Ch4 ; 11
    dw Song12_Ch2, Song12_Ch1, Song12_Ch3, Song12_Ch4 ; 12
    dw Song13_Ch2, Song13_Ch1, Song13_Ch3, Song13_Ch4 ; 13
